  constraint goal_enrollment_id_section_id_key UNIQUE (enrollment_id, section_id)
  constraint goal_pkey PRIMARY KEY (id)
  constraint goal_section_id_fkey FOREIGN KEY (section_id) REFERENCES public.section(id) ON DELETE CASCADE
  CREATE UNIQUE INDEX goal_enrollment_id_section_id_key ON public.goal USING btree (enrollment_id, section_id)
  CREATE UNIQUE INDEX goal_pkey ON public.goal USING btree (id)
  CREATE INDEX goal_section_idx ON public.goal USING btree (section_id)
  CREATE TRIGGER course_sync_cursor_goal_student_records AFTER INSERT OR DELETE OR UPDATE ON public.goal FOR EACH ROW EXECUTE FUNCTION public._touch_course_sync_cursor_from_trigger('student-records', 'enrollment')
  policy goal_via_enrollment for all to public using (public.fv_owns_enrollment(enrollment_id)) with check (public.fv_owns_enrollment(enrollment_id))
table public.grade_return (rls on)
  enrollment_id uuid not null
  assessment_id uuid not null
  is_draft boolean not null default false
  returned_at timestamp with time zone
  returned_copy jsonb
  previous_copy jsonb
  updated_at timestamp with time zone
  seen_at timestamp with time zone
  working_copy jsonb
  constraint grade_return_copy_while_draft CHECK (((returned_copy IS NOT NULL) = (is_draft AND (returned_at IS NOT NULL))))
  constraint grade_return_pkey PRIMARY KEY (enrollment_id, assessment_id)
  constraint grade_return_previous_copy_object CHECK (((previous_copy IS NULL) OR (jsonb_typeof(previous_copy) = 'object'::text)))
  constraint grade_return_returned_copy_object CHECK (((returned_copy IS NULL) OR (jsonb_typeof(returned_copy) = 'object'::text)))
  constraint grade_return_working_copy_object CHECK (((working_copy IS NULL) OR (jsonb_typeof(working_copy) = 'object'::text)))
  CREATE INDEX grade_return_assessment_idx ON public.grade_return USING btree (assessment_id)
  CREATE UNIQUE INDEX grade_return_pkey ON public.grade_return USING btree (enrollment_id, assessment_id)
  policy grade_return_read for select to public using (public.fv_owns_enrollment(enrollment_id))
table public.grade_return_repair_log (rls on)
  id bigint not null
  at timestamp with time zone not null default now()
  course_id uuid
  sqlstate text not null
  message text not null
  constraint grade_return_repair_log_pkey PRIMARY KEY (id)
  CREATE UNIQUE INDEX grade_return_repair_log_pkey ON public.grade_return_repair_log USING btree (id)
table public.guardian (rls on)
  id uuid not null default gen_random_uuid()
  student_id uuid not null
  name text not null
  relationship text
  email text
  phone text
  language text not null default 'en'::text
  consent_at timestamp with time zone
  consent_source text
  notes text
  created_at timestamp with time zone not null default now()
  updated_at timestamp with time zone not null default now()
  constraint guardian_consent_pair CHECK (((consent_at IS NULL) = (consent_source IS NULL)))
  constraint guardian_consent_source_check CHECK (((consent_source IS NULL) OR (consent_source = ANY (ARRAY['form'::text, 'verbal'::text, 'roster_import'::text, 'portal'::text]))))
  constraint guardian_email_check CHECK (((email IS NULL) OR ((char_length(email) <= 254) AND (email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text))))
  constraint guardian_language_check CHECK (((char_length(language) >= 2) AND (char_length(language) <= 12)))
  constraint guardian_name_check CHECK (((char_length(btrim(name)) >= 1) AND (char_length(btrim(name)) <= 120)))
  constraint guardian_notes_check CHECK (((notes IS NULL) OR (char_length(notes) <= 500)))
  constraint guardian_phone_check CHECK (((phone IS NULL) OR (char_length(phone) <= 40)))
  constraint guardian_pkey PRIMARY KEY (id)
  constraint guardian_relationship_check CHECK (((relationship IS NULL) OR (char_length(relationship) <= 40)))
  constraint guardian_student_id_fkey FOREIGN KEY (student_id) REFERENCES public.student(id) ON DELETE CASCADE
  CREATE UNIQUE INDEX guardian_pkey ON public.guardian USING btree (id)
  CREATE INDEX guardian_student ON public.guardian USING btree (student_id)
  CREATE UNIQUE INDEX guardian_student_email ON public.guardian USING btree (student_id, lower(email)) WHERE (email IS NOT NULL)
  policy guardian_owner for all to authenticated using ((EXISTS ( SELECT 1
   FROM public.student s
  WHERE ((s.id = guardian.student_id) AND (s.teacher_id = ( SELECT auth.uid() AS uid)))))) with check ((EXISTS ( SELECT 1
   FROM public.student s
  WHERE ((s.id = guardian.student_id) AND (s.teacher_id = ( SELECT auth.uid() AS uid))))))
table public.module (rls on)
  id uuid not null default gen_random_uuid()
  course_id uuid not null
  name text not null
  color text
  display_order integer not null default 0
