  updated_at timestamp with time zone not null default now()
  constraint module_color_format CHECK (((color IS NULL) OR (color ~ '^#[0-9a-fA-F]{6}([0-9a-fA-F]{2})?$'::text)))
  constraint module_course_id_fkey FOREIGN KEY (course_id) REFERENCES public.course(id) ON DELETE CASCADE
