  CREATE INDEX observation_tag_tag_idx ON public.observation_tag USING btree (tag_id)
  CREATE TRIGGER course_sync_cursor_observation_tag_student_records AFTER INSERT OR DELETE OR UPDATE ON public.observation_tag FOR EACH ROW EXECUTE FUNCTION public._touch_course_sync_cursor_from_trigger('student-records', 'observation')
  policy observation_tag_via_obs for all to public using ((EXISTS ( SELECT 1
   FROM public.observation o
