  teacher_id uuid not null
  constraint observation_template_course_id_fkey FOREIGN KEY (course_id) REFERENCES public.course(id) ON DELETE CASCADE
  constraint observation_template_default_sentiment_check CHECK (((default_sentiment IS NULL) OR (default_sentiment = ANY (ARRAY['strength'::text, 'growth'::text, 'concern'::text, 'note'::text]))))
  constraint observation_template_pkey PRIMARY KEY (id)
  constraint observation_template_teacher_id_fkey FOREIGN KEY (teacher_id) REFERENCES public.teacher(id) ON DELETE CASCADE
  CREATE INDEX observation_template_course_idx ON public.observation_template USING btree (course_id)
  CREATE UNIQUE INDEX observation_template_pkey ON public.observation_template USING btree (id)
  CREATE INDEX observation_template_teacher_idx ON public.observation_template USING btree (teacher_id, display_order)
  CREATE TRIGGER teacher_sync_cursor_observation_template_student_records AFTER INSERT OR DELETE OR UPDATE ON public.observation_template FOR EACH ROW EXECUTE FUNCTION public._touch_teacher_sync_cursor_from_trigger('student-records')
