table public.phone_report (rls on)
  id uuid not null default gen_random_uuid()
  course_id uuid not null
  term integer not null
  term_label text
  issued_at timestamp with time zone not null default now()
  updated_at timestamp with time zone not null default now()
  expires_on date not null
  closed_at timestamp with time zone
  created_by uuid
  constraint phone_report_course_id_fkey FOREIGN KEY (course_id) REFERENCES public.course(id) ON DELETE CASCADE
  constraint phone_report_created_by_fkey FOREIGN KEY (created_by) REFERENCES public.teacher(id) ON DELETE SET NULL
  constraint phone_report_pkey PRIMARY KEY (id)
  constraint phone_report_term_check CHECK (((term >= 1) AND (term <= 6)))
  constraint phone_report_term_label_check CHECK (((term_label IS NULL) OR (char_length(term_label) <= 80)))
  CREATE INDEX phone_report_course ON public.phone_report USING btree (course_id, issued_at DESC)
  CREATE INDEX phone_report_created_by_idx ON public.phone_report USING btree (created_by)
  CREATE UNIQUE INDEX phone_report_pkey ON public.phone_report USING btree (id)
  policy phone_report_via_course for all to public using (public.fv_owns_course(course_id)) with check (public.fv_owns_course(course_id))
table public.phone_report_student (rls on)
  report_id uuid not null
  enrollment_id uuid not null
  data jsonb not null
  updated_at timestamp with time zone not null default now()
  constraint phone_report_student_data_check CHECK (((jsonb_typeof(data) = 'object'::text) AND (octet_length((data)::text) <= 60000)))
  constraint phone_report_student_enrollment_id_fkey FOREIGN KEY (enrollment_id) REFERENCES public.enrollment(id) ON DELETE CASCADE
  constraint phone_report_student_pkey PRIMARY KEY (report_id, enrollment_id)
  constraint phone_report_student_report_id_fkey FOREIGN KEY (report_id) REFERENCES public.phone_report(id) ON DELETE CASCADE
  CREATE INDEX phone_report_student_enrollment_id_idx ON public.phone_report_student USING btree (enrollment_id)
  CREATE UNIQUE INDEX phone_report_student_pkey ON public.phone_report_student USING btree (report_id, enrollment_id)
  policy phone_report_student_via_report for all to public using ((EXISTS ( SELECT 1
   FROM public.phone_report r
  WHERE ((r.id = phone_report_student.report_id) AND public.fv_owns_course(r.course_id))))) with check ((EXISTS ( SELECT 1
   FROM public.phone_report r
  WHERE ((r.id = phone_report_student.report_id) AND public.fv_owns_course(r.course_id)))))
table public.question (rls on)
  id uuid not null default gen_random_uuid()
  questionnaire_id uuid not null
  display_order integer not null default 0
  prompt text not null
  prompt_translations jsonb not null default '{}'::jsonb
  kind text not null
  options jsonb not null default '{}'::jsonb
  core_ids text[] not null default '{}'::text[]
  repeated_key text
  teacher_only boolean not null default false
  archived boolean not null default false
  created_at timestamp with time zone not null default now()
  updated_at timestamp with time zone not null default now()
  constraint question_core_ids_check CHECK ((core_ids <@ ARRAY['COM'::text, 'COL'::text, 'CT'::text, 'CRT'::text, 'PPI'::text, 'PAR'::text, 'SAR'::text]))
  constraint question_kind_check CHECK ((kind = ANY (ARRAY['text'::text, 'short_set'::text, 'scale4'::text, 'choice'::text, 'goal_status'::text, 'core_pick'::text])))
  constraint question_options_check CHECK ((jsonb_typeof(options) = 'object'::text))
  constraint question_pkey PRIMARY KEY (id)
  constraint question_prompt_check CHECK (((char_length(btrim(prompt)) >= 1) AND (char_length(btrim(prompt)) <= 1000)))
  constraint question_prompt_translations_check CHECK ((jsonb_typeof(prompt_translations) = 'object'::text))
  constraint question_questionnaire_id_fkey FOREIGN KEY (questionnaire_id) REFERENCES public.questionnaire(id) ON DELETE CASCADE
  CREATE UNIQUE INDEX question_pkey ON public.question USING btree (id)
  CREATE INDEX question_questionnaire ON public.question USING btree (questionnaire_id, display_order)
  policy question_via_questionnaire for all to public using ((EXISTS ( SELECT 1
   FROM public.questionnaire q
  WHERE ((q.id = question.questionnaire_id) AND public.fv_owns_course(q.course_id))))) with check ((EXISTS ( SELECT 1
   FROM public.questionnaire q
  WHERE ((q.id = question.questionnaire_id) AND public.fv_owns_course(q.course_id)))))
table public.questionnaire (rls on)
  id uuid not null default gen_random_uuid()
  course_id uuid not null
  template_id text
  kind text not null
  title text not null
  theme text
  report_period integer
  parent_id uuid
  opens_on date
  closes_on date
  is_on boolean not null default true
  myed_comment text
  created_at timestamp with time zone not null default now()
  updated_at timestamp with time zone not null default now()
  constraint questionnaire_check CHECK (((opens_on IS NULL) OR (closes_on IS NULL) OR (opens_on <= closes_on)))
  constraint questionnaire_course_id_fkey FOREIGN KEY (course_id) REFERENCES public.course(id) ON DELETE CASCADE
  constraint questionnaire_kind_check CHECK ((kind = ANY (ARRAY['about_me'::text, 'core_reflection'::text, 'goal_checkin'::text, 'curricular_self_assessment'::text])))
  constraint questionnaire_parent_id_fkey FOREIGN KEY (parent_id) REFERENCES public.questionnaire(id) ON DELETE SET NULL
  constraint questionnaire_pkey PRIMARY KEY (id)
  constraint questionnaire_report_period_check CHECK (((report_period IS NULL) OR ((report_period >= 1) AND (report_period <= 6))))
  constraint questionnaire_template_id_fkey FOREIGN KEY (template_id) REFERENCES public.questionnaire_template(id) ON DELETE SET NULL
  constraint questionnaire_title_check CHECK (((char_length(btrim(title)) >= 1) AND (char_length(btrim(title)) <= 120)))
  CREATE INDEX questionnaire_course ON public.questionnaire USING btree (course_id)
  CREATE INDEX questionnaire_parent_id_idx ON public.questionnaire USING btree (parent_id)
  CREATE UNIQUE INDEX questionnaire_pkey ON public.questionnaire USING btree (id)
  CREATE INDEX questionnaire_template_id_idx ON public.questionnaire USING btree (template_id)
  policy questionnaire_via_course for all to public using (public.fv_owns_course(course_id)) with check (public.fv_owns_course(course_id))
table public.questionnaire_template (rls on)
  id text not null
  kind text not null
  grade integer
  period integer
  year integer not null default 2026
  title text not null
  theme text
  core_heading text
  myed_comment text
  questions jsonb not null default '[]'::jsonb
  updated_at timestamp with time zone not null default now()
  constraint questionnaire_template_grade_check CHECK (((grade IS NULL) OR ((grade >= 8) AND (grade <= 12))))
  constraint questionnaire_template_kind_check CHECK ((kind = ANY (ARRAY['about_me'::text, 'core_reflection'::text, 'goal_checkin'::text, 'curricular_self_assessment'::text])))
  constraint questionnaire_template_period_check CHECK (((period IS NULL) OR ((period >= 1) AND (period <= 3))))
  constraint questionnaire_template_pkey PRIMARY KEY (id)
  constraint questionnaire_template_questions_check CHECK ((jsonb_typeof(questions) = 'array'::text))
  CREATE UNIQUE INDEX questionnaire_template_pkey ON public.questionnaire_template USING btree (id)
  policy questionnaire_template_read for select to public using ((( SELECT auth.uid() AS uid) IS NOT NULL))
table public.reflection (rls on)
  id uuid not null default gen_random_uuid()
  enrollment_id uuid not null
  section_id uuid not null
  body text
  confidence integer
  created_at timestamp with time zone not null default now()
  updated_at timestamp with time zone not null default now()
