table public.term_rating (rls on)
  id uuid not null default gen_random_uuid()
  enrollment_id uuid not null
  term integer not null
  narrative_html text
  work_habits_rating integer
  participation_rating integer
  social_traits text[] not null default '{}'::text[]
  created_at timestamp with time zone not null default now()
  updated_at timestamp with time zone not null default now()
  absences integer
  lates integer
  habits jsonb not null default '{}'::jsonb
  approved_at timestamp with time zone
  reporting_basis text not null default 'grade'::text
  ie_deadline date
  draft_meta jsonb
  constraint term_rating_absences_check CHECK ((absences >= 0))
  constraint term_rating_draft_meta_object CHECK (((draft_meta IS NULL) OR (jsonb_typeof(draft_meta) = 'object'::text)))
  constraint term_rating_enrollment_id_fkey FOREIGN KEY (enrollment_id) REFERENCES public.enrollment(id) ON DELETE CASCADE
  constraint term_rating_enrollment_id_term_key UNIQUE (enrollment_id, term)
  constraint term_rating_habits_object CHECK ((jsonb_typeof(habits) = 'object'::text))
  constraint term_rating_ie_needs_deadline CHECK (((reporting_basis <> 'ie'::text) OR (ie_deadline IS NOT NULL)))
  constraint term_rating_lates_check CHECK ((lates >= 0))
  constraint term_rating_participation_rating_check CHECK (((participation_rating >= 1) AND (participation_rating <= 4)))
  constraint term_rating_pkey PRIMARY KEY (id)
  constraint term_rating_reporting_basis_check CHECK ((reporting_basis = ANY (ARRAY['grade'::text, 'ie'::text, 'language_goals'::text, 'iep_goals'::text])))
  constraint term_rating_term_check CHECK (((term >= 1) AND (term <= 6)))
  constraint term_rating_work_habits_rating_check CHECK (((work_habits_rating >= 1) AND (work_habits_rating <= 4)))
  CREATE UNIQUE INDEX term_rating_enrollment_id_term_key ON public.term_rating USING btree (enrollment_id, term)
  CREATE INDEX term_rating_enrollment_idx ON public.term_rating USING btree (enrollment_id)
  CREATE UNIQUE INDEX term_rating_pkey ON public.term_rating USING btree (id)
  CREATE TRIGGER course_sync_cursor_term_rating_student_records AFTER INSERT OR DELETE OR UPDATE ON public.term_rating FOR EACH ROW EXECUTE FUNCTION public._touch_course_sync_cursor_from_trigger('student-records', 'enrollment')
  policy term_rating_via_enrollment for all to public using (public.fv_owns_enrollment(enrollment_id)) with check (public.fv_owns_enrollment(enrollment_id))
